a1 = arr[5, 1, 4, 2, 8]

fun Bubble_Sort(@init<table> array):
    n = length(array)
    for (i = 0; i < n; i += 1):
        for (j = 0; j < n - i - 1; j += 1):
            @mark<j, outline, yellow> if (array[j] > array[j + 1]):
                @mark<j, highlight, green> swap(array[j], array[j + 1])
            end if
        end for
    end for
    return array
end fun

sorted_a1 = Bubble_Sort(a1)

// Binary Search

fun Binary_Search(@init<table> array, target, low, high):
    @mark<low, outline, yellow> @mark<high, outline, yellow> if (low > high):
        @log<warn, "Not found"> return -1
    end if

    mid = floor((low + high) / 2)
    @mark<mid, highlight, yellow> val = array[mid]

    if (val == target):
        @mark<mid, highlight, green> return mid
    elsif (val < target):
        @mark<low, outline, yellow> low = mid + 1
        return Binary_Search(array, target, low, high)
    else:
        @mark<high, outline, yellow> high = mid - 1
        return Binary_Search(array, target, low, high)
    end if
end fun

target_index = Binary_Search(sorted_a1, 4, 0, size(sorted_a1) - 1)

result = target_index
```

