fun Dutch_National_Flag(@init<table> array):
    n = length(array)

    low = 0
    mid = 0
    high = n - 1

    while (mid <= high):
        if (array[mid] == 0):
            @swap<mid, low> low += 1
            mid += 1
        elif (array[mid] == 2):
            @swap<mid, high> high -= 1
        else:
            mid += 1
        end if
    end while

    return array
end fun

