// Majority Element Finder

// Initialize input array
a1 = arr[3, 3, 4, 2, 4, 4, 2, 4, 4]

fun Boyer_Moore_Voting_Algorithm(@init<table> array):
    candidate = -1
    count = 0

    // Phase 1: Find a candidate
    for (i = 0; i < size(array); i += 1):
        @mark<i, outline, yellow> if (count == 0):
            @mark<i, highlight, yellow> candidate = array[i]
            @mark<i, highlight, green> count = 1
        end if

        @mark<i, outline, yellow> if (array[i] == candidate):
            @mark<i, highlight, green> count += 1
        end if

        @mark<i, outline, yellow> if (array[i] != candidate):
            @mark<i, highlight, green> count -= 1
        end if
    end for

    // Phase 2: Verify the candidate
    count = 0
    for (i = 0; i < size(array); i += 1):
        @mark<i, outline, yellow> if (array[i] == candidate):
            @mark<i, highlight, green> count += 1
        end if
    end for

    @mark<count, outline, yellow> if (count > size(array) / 2):
        @mark<count, highlight, green> return candidate
    else:
        @log<warn, "No majority element found"> return -1
    end if
end fun

result = Boyer_Moore_Voting_Algorithm(a1)
```

### Explanation:
1. **Initialization**: The input array `a1` is initialized with `[3, 3, 4, 2, 4, 4, 2, 4, 4]`.
