fun Merge_Sort(@init<table> array):
    n = length(array)
    temp = arr[n]  // create temporary array

    // Initialize the temporary array with values from the original array
    for (i = 0; i < n; i += 1):
        temp[i] = array[i]
    end for

    merge_sort_recursive(temp, 0, n - 1, array)

    return array
end fun

fun merge_sort_recursive(@init<table> temp, low, high, @init<table> array):
    if (low < high):
        mid = floor((low + high) / 2)

        merge_sort_recursive(temp, low, mid, array)
        merge_sort_recursive(temp, mid + 1, high, array)

        merge(temp, low, mid, high, array)
    end if
end fun

fun merge(@init<table> temp, low, mid, high, @init<table> array):
    i = low
    j = mid + 1
    k = low

    while (i <= mid and j <= high):
        if (temp[i] <= temp[j]):
            @mark<k, highlight, green> array[k] = temp[i]
            i += 1
        else:
            @mark<k, highlight, green> array[k] = temp[j]
            j += 1
        end if
        k += 1
    end while

    // Copy the remaining elements of left subarray, if any
    while (i <= mid):
        @mark<k, highlight, green> array[k] = temp[i]
        i += 1
        k += 1
    end while

    // Copy the remaining elements of right subarray, if any
    while (j <= high):
        @mark<k, highlight, green> array[k] = temp[j]
        j += 1
        k += 1
    end while
end fun

