        @log<info, "Recursive call on left partition"> Quick_Sort(array, low, pi)

        @log<info, "Recursive call on right partition"> Quick_Sort(array, pi + 1, high)

    end if
    return array
end fun

fun Hoare_Partition(@init<table> array, low, high):
    @mark<low, highlight, yellow> pivot = array[low]
    i = low - 1
    j = high + 1

    while (true):
        while (true):
            i += 1
            @mark<i, outline, yellow> if (array[i] >= pivot or i >= high):
                break
            end if
        end while

        while (true):
            j -= 1
            @mark<j, outline, yellow> if (array[j] <= pivot or j <= low):
                break
            end if
        end while

        if (i >= j):
            @log<info, "Partition complete"> return j
        end if

        @mark<i, highlight, green> swap (array[i], array[j])

    end while
end fun

