// Two Pointers to Find Pair Sum

a1 = arr[1, 2, 3, 4, 5, 6, 7, 8, 9]

fun Two_Pointer_PairSum(@init<table> array, target):
    n = length(array)

    // Initialize two pointers
    i = 0
    j = n - 1

    while (i < j):
        @mark<i, outline, yellow> sum = array[i] + array[j]

        if (sum == target):
            @log<info, "Pair found"> return arr[i, j]
        elseif (sum < target):
            @mark<i, highlight, green> i += 1
        else:
            @mark<j, highlight, green> j -= 1
        end if
    end while

    @log<warn, "No pair found"> return arr[-1, -1]
end fun

result = Two_Pointer_PairSum(a1, 10)
