fun Two_Sum(@init<table> array, int target):
    int n = length(array)

    // Initialize two pointers
    int i = 0
    int j = n - 1

    while (i < j):
        @mark<i, outline, yellow>
        @mark<j, outline, yellow>

        if (array[i] + array[j] == target):
            @log<info, "Pair found at indices " + i + ", " + j>
            return arr[i, j]
        else if (array[i] + array[j] < target):
            @mark<i, highlight, green>
            i += 1
        else:
            @mark<j, highlight, green>
            j -= 1

    end while

    @log<warn, "No pair found">
    return arr[-1, -1]
end fun

result = Two_Sum(arr, target)
```

